import sys
from collections import defaultdict

class Solution:
    def solve(self, n, edges, power, cost, source, target):
        adj = defaultdict(list)
        for u, v, t in edges:
            adj[u].append((v, t))
        self.best_t, self.best_p = float('inf'), -1
        visited = [False] * n
        visited[source] = True

        def dfs(u, time, pw):
            if u == target:
                if time < self.best_t or (time == self.best_t and pw > self.best_p):
                    self.best_t, self.best_p = time, pw
                return
            for v, t in adj[u]:
                if not visited[v] and pw >= cost[u]:
                    visited[v] = True
                    dfs(v, time + t, pw - cost[u])
                    visited[v] = False

        dfs(source, 0, power)
        return [-1, -1] if self.best_t == float('inf') else [self.best_t, self.best_p]

