import heapq
from collections import defaultdict

class Solution:
    def solve(self, n, edges, power, cost, source, target):
        adj = defaultdict(list)
        for u, v, t in edges:
            adj[u].append((v, t))
        INF = float('inf')
        best = [[INF] * (power + 1) for _ in range(n)]
        best[source][power] = 0
        heap = [(0, -power, source, power)]
        while heap:
            d, negp, u, p = heapq.heappop(heap)
            if best[u][p] < d:
                continue
            if p >= cost[u]:
                q = p - cost[u]
                for v, t in adj[u]:
                    nd = d + t
                    if nd < best[v][q]:
                        best[v][q] = nd
                        heapq.heappush(heap, (nd, -q, v, q))
        mt = min(best[target])
        if mt == INF:
            return [-1, -1]
        mp = max(p for p in range(power + 1) if best[target][p] == mt)
        return [mt, mp]

