import java.util.*;

class Solution {
    public int[] solve(int n, int[][] edges, int power, int[] cost, int source, int target) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) adj.get(e[0]).add(new int[]{e[1], e[2]});
        final long INF = Long.MAX_VALUE;
        long[][] best = new long[n][power + 1];
        for (long[] row : best) Arrays.fill(row, INF);
        best[source][power] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        pq.offer(new long[]{0, -power, source, power});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long d = cur[0]; int u = (int) cur[2], p = (int) cur[3];
            if (best[u][p] < d) continue;
            if (p < cost[u]) continue;
            int q = p - cost[u];
            for (int[] ed : adj.get(u)) {
                int v = ed[0], t = ed[1];
                long nd = d + t;
                if (nd < best[v][q]) {
                    best[v][q] = nd;
                    pq.offer(new long[]{nd, -q, v, q});
                }
            }
        }
        long mt = INF;
        for (int p = 0; p <= power; p++) mt = Math.min(mt, best[target][p]);
        if (mt == INF) return new int[]{-1, -1};
        int mp = 0;
        for (int p = 0; p <= power; p++) if (best[target][p] == mt) mp = p;
        return new int[]{(int) mt, mp};
    }
}

