var solve = function(n, edges, power, cost, source, target) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, t] of edges) adj[u].push([v, t]);
    const INF = Infinity;
    const best = Array.from({length: n}, () => new Array(power + 1).fill(INF));
    best[source][power] = 0;
    // Min-heap via array sort (states are few enough); key: time asc, then -power asc (= power desc)
    let heap = [[0, -power, source, power]];
    while (heap.length) {
        heap.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
        const [d, , u, p] = heap.shift();
        if (best[u][p] < d) continue;
        if (p < cost[u]) continue;
        const q = p - cost[u];
        for (const [v, t] of adj[u]) {
            const nd = d + t;
            if (nd < best[v][q]) {
                best[v][q] = nd;
                heap.push([nd, -q, v, q]);
            }
        }
    }
    let mt = INF;
    for (let p = 0; p <= power; p++) mt = Math.min(mt, best[target][p]);
    if (mt === INF) return [-1, -1];
    let mp = 0;
    for (let p = 0; p <= power; p++) if (best[target][p] === mt) mp = p;
    return [mt, mp];
};
